import { mapProductFields } from './product-fields.js';

const DEFAULT_SOURCE = 'pdp_fbt';

export default class ProductClicked {
    constructor(details) {
        this.item = details[0];
        // The emitting section names itself (`pdp_fbt`, `basket_gap`, …). Falls back to
        // FBT, which was the only emitter before the source became explicit.
        this.source = this.item?.source || DEFAULT_SOURCE;
        this.requestId = this.item?.request_id ?? null;
    }

    static shouldSend(details) {
        return !!details?.[0]?.product && !!details?.[0]?.position;
    }

    toSegment() {
        const { product, position } = this.item;
        return {
            event: 'Product Clicked',
            properties: {
                ...mapProductFields(product, position),
                source: this.source,
                request_id: this.requestId,
            },
        };
    }
}
